const sessionId = $json.sessionId;
const userMessage = ($json.chatInput || '').trim();
const msgLower = userMessage.toLowerCase();

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.loginAttempts) staticData.loginAttempts = {};

let session = staticData.sessions[sessionId] || {
  step: -1,
  authenticated: false,
  userId: null,
  username: null,
  sessionToken: null,
  pendingField: null
};

let response = '';
let action = 'none';
let actionData = {};

function resetToMenu() {
  session.step = session.authenticated ? -2 : -1;
}

function requireAuth() {
  if (!session.authenticated || !session.sessionToken) {
    response = 'Session expirée ou non connectée. Tape "connexion" pour te reconnecter.';
    resetToMenu();
    return false;
  }
  return true;
}

function cancelFlow() {
  resetToMenu();
  response = session.authenticated
    ? 'Action annulée. Que veux-tu faire ? (profil / rgpd / déconnexion / aide)'
    : 'Action annulée. Tape "inscription" ou "connexion".';
}

if (msgLower === 'annuler' || msgLower === 'cancel') {
  cancelFlow();
} else if (!session.authenticated) {
  // ---- NON AUTHENTIFIÉ ----
  if (session.step === -1) {
    if (msgLower.includes('inscri') || msgLower.includes('créer') || msgLower.includes('creer')) {
      session.step = 0;
      response = 'Inscription Persona\n\nChoisis un nom d\'utilisateur (3-20 caractères, lettres/chiffres/_).';
    } else if (msgLower.includes('connect') || msgLower.includes('login')) {
      session.step = 10;
      response = 'Connexion\n\nQuel est ton nom d\'utilisateur ?';
    } else if (msgLower.includes('aide') || msgLower.includes('help')) {
      response = 'Persona - Aide\n\n• "inscription" : créer un compte\n• "connexion" : se connecter\n• "aide" : cette aide\n\nAprès connexion : profil, rgpd, déconnexion.';
    } else {
      response = 'Bonjour ! Je suis Persona.\n\nTape "inscription" pour créer un compte ou "connexion" pour te connecter.';
    }
  } else if (session.step === 0) {
    if (!/^[a-zA-Z0-9_]{3,20}$/.test(userMessage)) {
      response = 'Nom invalide. Utilise 3-20 caractères (lettres, chiffres, underscore).';
    } else {
      session.username = userMessage;
      session.step = 1;
      response = `Parfait ${session.username} ! Choisis un mot de passe (min. 8 car., lettre + chiffre).`;
    }
  } else if (session.step === 1) {
    if (userMessage.length < 8 || !/[A-Za-z]/.test(userMessage) || !/\d/.test(userMessage)) {
      response = 'Mot de passe trop faible. Min. 8 caractères avec au moins une lettre et un chiffre.';
    } else {
      session.password = userMessage;
      session.step = 2;
      response = 'Confirme ton mot de passe.';
    }
  } else if (session.step === 2) {
    if (userMessage !== session.password) {
      session.step = 1;
      delete session.password;
      response = 'Les mots de passe ne correspondent pas. Rechoisis un mot de passe.';
    } else {
      session.step = 3;
      response = 'Quelle est ton adresse email ?';
    }
  } else if (session.step === 3) {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userMessage)) {
      response = 'Email invalide. Exemple : prenom@domaine.com';
    } else {
      session.email = userMessage;
      session.step = 4;
      response = 'Quels sont tes centres d\'intérêt ? (ex: IA, sport, économie)';
    }
  } else if (session.step === 4) {
    if (userMessage.length < 2) {
      response = 'Indique au moins un centre d\'intérêt.';
    } else {
      session.interests = userMessage;
      session.step = 5;
      response = 'À quelle heure veux-tu recevoir ta newsletter ? (format HH:MM, ex: 08:00)';
    }
  } else if (session.step === 5) {
    if (!/^([01]?\d|2[0-3]):[0-5]\d$/.test(userMessage)) {
      response = 'Heure invalide. Utilise le format HH:MM (ex: 08:00).';
    } else {
      session.schedule_time = userMessage;
      session.step = 6;
      response = 'Consentement RGPD\n\nPersona stocke ton email, tes intérêts et ton horaire pour t\'envoyer une newsletter personnalisée. Tu peux te désinscrire ou supprimer tes données à tout moment.\n\nAcceptes-tu ? (oui/non)';
    }
  } else if (session.step === 6) {
    if (['oui', 'yes', 'o', 'y'].includes(msgLower)) {
      action = 'register';
      actionData = {
        username: session.username,
        password: session.password,
        email: session.email,
        interests: session.interests,
        schedule_time: session.schedule_time
      };
      response = 'Création de ton compte en cours...';
      delete session.password;
      session.step = -1;
    } else if (['non', 'no', 'n'].includes(msgLower)) {
      staticData.sessions[sessionId] = { step: -1, authenticated: false };
      response = 'Inscription annulée sans stockage de données. Tu peux recommencer avec "inscription".';
      session = staticData.sessions[sessionId];
    } else {
      response = 'Réponds "oui" ou "non" pour le consentement RGPD.';
    }
  } else if (session.step === 10) {
    session.loginUsername = userMessage;
    session.step = 11;
    response = 'Quel est ton mot de passe ?';
  } else if (session.step === 11) {
    action = 'login';
    actionData = { username: session.loginUsername, password: userMessage };
    response = 'Vérification en cours...';
    session.step = -1;
    delete session.loginUsername;
  }
} else {
  // ---- AUTHENTIFIÉ ----
  if (session.step === -2) {
    if (msgLower.includes('profil') || msgLower.includes('profile')) {
      session.step = 20;
      response = 'Mon profil\n\n1. Voir mon profil\n2. Modifier email\n3. Modifier intérêts\n4. Modifier horaire\n\nTape le numéro ou "annuler".';
    } else if (msgLower.includes('rgpd') || msgLower.includes('données') || msgLower.includes('donnees')) {
      session.step = 30;
      response = 'Gestion RGPD\n\n1. Voir mes données\n2. Me désinscrire (newsletter)\n3. Supprimer mon compte\n\nTape le numéro ou "annuler".';
    } else if (msgLower.includes('déconnexion') || msgLower.includes('deconnexion') || msgLower.includes('logout')) {
      action = 'logout';
      actionData = { sessionToken: session.sessionToken };
      session.authenticated = false;
      session.sessionToken = null;
      session.userId = null;
      session.username = null;
      session.step = -1;
      response = 'Déconnexion en cours...';
    } else if (msgLower.includes('aide') || msgLower.includes('help')) {
      response = `Connecté en tant que ${session.username}.\n\n• profil : gérer tes infos\n• rgpd : données personnelles\n• déconnexion : fermer la session\n• annuler : revenir au menu`;
    } else {
      response = `Bonjour ${session.username} !\n\nQue veux-tu faire ?\n• profil\n• rgpd\n• déconnexion\n• aide`;
    }
  } else if (session.step === 20) {
    if (msgLower === '1' || msgLower.includes('voir')) {
      action = 'profile_view';
      actionData = { sessionToken: session.sessionToken };
      session.step = -2;
      response = 'Chargement de ton profil...';
    } else if (msgLower === '2' || msgLower.includes('email')) {
      session.step = 21;
      session.pendingField = 'email';
      response = 'Nouvelle adresse email ?';
    } else if (msgLower === '3' || msgLower.includes('intérêt') || msgLower.includes('interet')) {
      session.step = 21;
      session.pendingField = 'interests';
      response = 'Nouveaux centres d\'intérêt ?';
    } else if (msgLower === '4' || msgLower.includes('horaire') || msgLower.includes('heure')) {
      session.step = 21;
      session.pendingField = 'schedule_time';
      response = 'Nouvel horaire ? (HH:MM)';
    } else {
      session.step = -2;
      response = 'Retour au menu. Tape profil, rgpd ou déconnexion.';
    }
  } else if (session.step === 21) {
    if (!requireAuth()) {
      // response already set
    } else if (session.pendingField === 'email') {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userMessage)) {
        response = 'Email invalide.';
      } else {
        action = 'profile_update';
        actionData = { sessionToken: session.sessionToken, field: 'email', value: userMessage };
        session.step = -2;
        session.pendingField = null;
        response = 'Mise à jour de ton email...';
      }
    } else if (session.pendingField === 'interests') {
      if (userMessage.length < 2) {
        response = 'Indique au moins un centre d\'intérêt.';
      } else {
        action = 'profile_update';
        actionData = { sessionToken: session.sessionToken, field: 'interests', value: userMessage };
        session.step = -2;
        session.pendingField = null;
        response = 'Mise à jour de tes intérêts...';
      }
    } else if (session.pendingField === 'schedule_time') {
      if (!/^([01]?\d|2[0-3]):[0-5]\d$/.test(userMessage)) {
        response = 'Heure invalide (HH:MM).';
      } else {
        action = 'profile_update';
        actionData = { sessionToken: session.sessionToken, field: 'schedule_time', value: userMessage };
        session.step = -2;
        session.pendingField = null;
        response = 'Mise à jour de ton horaire...';
      }
    }
  } else if (session.step === 30) {
    if (!requireAuth()) {
      // response already set
    } else if (msgLower === '1' || msgLower.includes('voir')) {
      action = 'gdpr_export';
      actionData = { sessionToken: session.sessionToken };
      session.step = -2;
      response = 'Export de tes données...';
    } else if (msgLower === '2' || msgLower.includes('désinscri') || msgLower.includes('desinscri')) {
      session.step = 31;
      response = 'Confirmer la désinscription newsletter ? Tu garderas ton compte mais ne recevras plus d\'emails. (oui/non)';
    } else if (msgLower === '3' || msgLower.includes('supprim')) {
      session.step = 32;
      response = 'ATTENTION : suppression définitive de toutes tes données. Confirme en tapant exactement : SUPPRIMER MON COMPTE';
    } else {
      session.step = -2;
      response = 'Retour au menu.';
    }
  } else if (session.step === 31) {
    if (['oui', 'yes'].includes(msgLower)) {
      action = 'gdpr_unsubscribe';
      actionData = { sessionToken: session.sessionToken };
      session.step = -2;
      response = 'Désinscription en cours...';
    } else if (['non', 'no'].includes(msgLower)) {
      session.step = -2;
      response = 'Désinscription annulée.';
    } else {
      response = 'Réponds oui ou non.';
    }
  } else if (session.step === 32) {
    if (userMessage === 'SUPPRIMER MON COMPTE') {
      action = 'gdpr_delete';
      actionData = { sessionToken: session.sessionToken };
      session.authenticated = false;
      session.sessionToken = null;
      session.userId = null;
      session.username = null;
      session.step = -1;
      response = 'Suppression de ton compte en cours...';
    } else {
      session.step = -2;
      response = 'Suppression annulée. Retour au menu.';
    }
  } else {
    session.step = -2;
    response = `Bonjour ${session.username} ! Tape profil, rgpd ou déconnexion.`;
  }
}

staticData.sessions[sessionId] = session;

return {
  json: {
    output: response,
    action,
    actionData,
    sessionId,
    session
  }
};

const staticData = $getWorkflowStaticData('global');
const processData = $('Process Message').first().json;
const sessionId = processData.sessionId;
let session = staticData.sessions[sessionId] || processData.session;
let response = processData.output;
const action = processData.action;
const result = $input.first().json;

if (action === 'none') {
  return { json: { output: response } };
}

if (action === 'register') {
  if (result.success) {
    session.authenticated = true;
    session.sessionToken = result.sessionToken;
    session.userId = result.userId;
    session.username = result.username;
    session.step = -2;
    response = `Compte créé ! Bienvenue ${result.username}.\n\nTu es connecté. Tape "profil" pour voir/modifier tes infos ou "aide".`;
  } else {
    session.step = -1;
    response = result.error || 'Erreur lors de l\'inscription.';
  }
} else if (action === 'login') {
  if (result.success) {
    session.authenticated = true;
    session.sessionToken = result.sessionToken;
    session.userId = result.userId;
    session.username = result.username;
    session.step = -2;
    response = `Connexion réussie ! Bonjour ${result.username}.\n\nTape "profil", "rgpd" ou "aide".`;
  } else {
    response = result.error || 'Identifiants incorrects.';
  }
} else if (action === 'logout') {
  response = 'Tu es déconnecté. Tape "connexion" pour te reconnecter.';
} else if (action === 'profile_view') {
  if (result.success) {
    response = `Ton profil :\n• Utilisateur : ${result.username}\n• Email : ${result.email}\n• Intérêts : ${result.interests}\n• Horaire : ${result.schedule_time}\n• Newsletter : ${result.active ? 'active' : 'désactivée'}`;
  } else {
    response = result.error || 'Impossible de charger le profil.';
  }
} else if (action === 'profile_update') {
  response = result.success
    ? `Profil mis à jour : ${result.field} = ${result.value}`
    : (result.error || 'Erreur de mise à jour.');
} else if (action === 'gdpr_export') {
  if (result.success) {
    response = `Export RGPD (Art. 15/20) :\n${JSON.stringify(result.data, null, 2)}\n\nAucune donnée n\'est partagée avec d\'autres utilisateurs.`;
  } else {
    response = result.error || 'Export impossible.';
  }
} else if (action === 'gdpr_unsubscribe') {
  response = result.success
    ? 'Tu es désinscrit de la newsletter. Ton compte reste actif. Tu peux te réabonner via "profil".'
    : (result.error || 'Erreur de désinscription.');
} else if (action === 'gdpr_delete') {
  response = result.success
    ? 'Ton compte et toutes tes données personnelles ont été supprimés conformément au RGPD.'
    : (result.error || 'Erreur de suppression.');
}

staticData.sessions[sessionId] = session;
return { json: { output: response } };
